from itertools import product

n = 21
# Fixed sequence values
fixed_seq = {5: -1, 12: -1, 17: 1, 20: 1}
free_indices = [i for i in range(n) if i not in fixed_seq]

# Interpret c[k] as C_{k+1} (autocorrelation at lag k+1)
# c[0]=2 means C_1=2, c[1]=-1 means C_2=-1, c[8]=2 means C_9=2, c[19]=-1 means C_20=-1
c_constraints = {0: 2, 1: -1, 8: 2, 19: -1}

def compute_autocorrelation(seq):
    C = []
    for k in range(1, n):
        c_k = sum(seq[i] * seq[i+k] for i in range(n-k))
        C.append(c_k)
    return C

def check_constraints(seq):
    # Check seq constraints
    for idx, val in fixed_seq.items():
        if seq[idx] != val:
            return False

    # Compute autocorrelation
    C = compute_autocorrelation(seq)

    # Check sum of squares
    sum_sq = sum(c**2 for c in C)
    if sum_sq > 52:
        return False

    # Check c constraints (c[k] = C[k] where C is 0-indexed list of C_1, C_2, ..., C_20)
    for k, val in c_constraints.items():
        if C[k] != val:
            return False

    return True

# Brute force search
print(f"Searching over {2**len(free_indices)} sequences...")
count = 0
for values in product([-1, 1], repeat=len(free_indices)):
    seq = [0] * n
    for idx, val in zip(free_indices, values):
        seq[idx] = val
    for idx, val in fixed_seq.items():
        seq[idx] = val

    if check_constraints(seq):
        print("Found solution:", seq)
        C = compute_autocorrelation(seq)
        print("Autocorrelation (C_1 to C_20):", C)
        print("Sum of squares:", sum(c**2 for c in C))
        break
    count += 1
    if count % 50000 == 0:
        print(f"Checked {count} sequences...")
else:
    print("No solution found with c[k]=C_{k+1} interpretation")
